// The curves' maths, as core's src/rendering/curve.ts has it: the same
// interpolation draws the curve in core's CurveEditor and builds the masks'
// tables, so a curve renders as the editor shows it.

import type { CurvePoint, ToneCurves } from "./safelight";

// Monotone cubic Hermite interpolation (Fritsch–Carlson). Produces smooth,
// overshoot-free tone curves through the control points — the standard choice
// for photo tone curves.
export function makeCurveEvaluator(
  points: CurvePoint[],
): (x: number) => number {
  const sorted = [...points].sort((a, b) => a.x - b.x);
  const n = sorted.length;

  if (n === 0) return (x) => x;
  if (n === 1) return () => clamp01(sorted[0].y);

  const xs = sorted.map((p) => p.x);
  const ys = sorted.map((p) => p.y);

  // Secant slopes between consecutive points.
  const delta: number[] = [];
  for (let i = 0; i < n - 1; i++) {
    const dx = xs[i + 1] - xs[i];
    delta.push(dx === 0 ? 0 : (ys[i + 1] - ys[i]) / dx);
  }

  // Tangents.
  const m: number[] = new Array(n);
  m[0] = delta[0];
  m[n - 1] = delta[n - 2];
  for (let i = 1; i < n - 1; i++) {
    m[i] = delta[i - 1] * delta[i] <= 0 ? 0 : (delta[i - 1] + delta[i]) / 2;
  }

  // Enforce monotonicity.
  for (let i = 0; i < n - 1; i++) {
    if (delta[i] === 0) {
      m[i] = 0;
      m[i + 1] = 0;
      continue;
    }
    const a = m[i] / delta[i];
    const b = m[i + 1] / delta[i];
    const s = a * a + b * b;
    if (s > 9) {
      const t = 3 / Math.sqrt(s);
      m[i] = t * a * delta[i];
      m[i + 1] = t * b * delta[i];
    }
  }

  return (x: number): number => {
    if (x <= xs[0]) return clamp01(ys[0]);
    if (x >= xs[n - 1]) return clamp01(ys[n - 1]);

    let i = 0;
    while (i < n - 1 && x > xs[i + 1]) i++;

    const h = xs[i + 1] - xs[i];
    const t = (x - xs[i]) / h;
    const t2 = t * t;
    const t3 = t2 * t;

    const h00 = 2 * t3 - 3 * t2 + 1;
    const h10 = t3 - 2 * t2 + t;
    const h01 = -2 * t3 + 3 * t2;
    const h11 = t3 - t2;

    const y =
      h00 * ys[i] + h10 * h * m[i] + h01 * ys[i + 1] + h11 * h * m[i + 1];
    return clamp01(y);
  };
}

// Compose the master (RGB) curve with each per-channel curve into one 256×1
// RGBA LUT. Order matches LR: the user's master curve, then the channel's own
// curve, so finalChannel[i] = channelCurve(rgbCurve(i)). The shader samples
// .r/.g/.b. The default baseline look is not in here — it is baselineTone in
// the shader, applied in linear light and gated to RAW sources. Float
// evaluators compose continuously and quantize ONCE at the end — chaining 8-bit
// LUT lookups compounds rounding into visible posterization.
function composeCurves(curves: ToneCurves, write: (index: number, r: number, g: number, b: number) => void): void {
  const rgbEval = makeCurveEvaluator(curves.rgb);
  const redEval = makeCurveEvaluator(curves.red);
  const greenEval = makeCurveEvaluator(curves.green);
  const blueEval = makeCurveEvaluator(curves.blue);

  for (let i = 0; i < 256; i++) {
    const base = rgbEval(i / 255);
    write(i, redEval(base), greenEval(base), blueEval(base));
  }
}

/** The 8-bit table of process version 1, whose output is frozen. */
export function buildRGBCurveLUT(curves: ToneCurves): Uint8Array {
  const out = new Uint8Array(256 * 4);
  composeCurves(curves, (i, r, g, b) => {
    out[i * 4] = Math.round(r * 255);
    out[i * 4 + 1] = Math.round(g * 255);
    out[i * 4 + 2] = Math.round(b * 255);
    out[i * 4 + 3] = 255;
  });
  return out;
}

/** The same table unquantized, so a gentle curve keeps its sub-1/255 steps. */
export function buildRGBCurveLUTFloat(curves: ToneCurves): Float32Array {
  const out = new Float32Array(256 * 4);
  composeCurves(curves, (i, r, g, b) => {
    out[i * 4] = r;
    out[i * 4 + 1] = g;
    out[i * 4 + 2] = b;
    out[i * 4 + 3] = 1;
  });
  return out;
}

/** True when every curve is the straight line from (0, 0) to (1, 1). */
export function isDefaultToneCurves(c: ToneCurves): boolean {
  return (["rgb", "red", "green", "blue"] as const).every((ch) => {
    const pts = c[ch];
    return pts.length === 2 && pts[0].x === 0 && pts[0].y === 0 && pts[1].x === 1 && pts[1].y === 1;
  });
}

function clamp01(v: number): number {
  return v < 0 ? 0 : v > 1 ? 1 : v;
}
